class Solution:
    def maximumXorProduct(self, a, b, n):
        MOD = 10 ** 9 + 7
        A, B = a, b
        for i in range(n - 1, -1, -1):
            bit = 1 << i
            ab, bb = A & bit, B & bit
            if ab == bb:
                if not ab:
                    A |= bit; B |= bit
            else:
                if A > B:
                    A, B = B, A
                if B & bit:
                    B ^= bit; A |= bit
                else:
                    A ^= bit; B |= bit
        return (A % MOD) * (B % MOD) % MOD

