class Solution {
public:
    int maximumXorProduct(long long a, long long b, int n) {
        const long long MOD = 1e9 + 7;
        unsigned long long A = a, B = b;
        for (int i = n - 1; i >= 0; i--) {
            unsigned long long bit = 1ULL << i;
            bool ab = A & bit, bb = B & bit;
            if (ab == bb) {
                if (!ab) { A |= bit; B |= bit; }
            } else {
                if (A > B) swap(A, B);
                if (B & bit) { B ^= bit; A |= bit; }
                else { A ^= bit; B |= bit; }
            }
        }
        return (int)((A % MOD) * (B % MOD) % MOD);
    }
};

