        MOD = 10 ** 9 + 7
        x = 0
        for i in range(n):
            bit = 1 << i
            if ((a >> i) & 1) == ((b >> i) & 1):
                if not (a >> i) & 1:
                    x |= bit
        A, B = a ^ x, b ^ x
        for i in range(n - 1, -1, -1):
            bit = 1 << i
            if ((a >> i) & 1) != ((b >> i) & 1):
                if A <= B: A |= bit
                else: B |= bit
        return (A % MOD) * (B % MOD) % MOD

